/* IServe public site script. Reads window.ISERVE (generated by tools/build.py from /data). */
(() => {
  const C = window.ISERVE;
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const wa = (t) => `https://wa.me/${C.whatsapp}?text=${encodeURIComponent(t)}`;
  // Conversion events. Sent only if Google Tag Manager or GA4 was configured at build time (no IDs = nothing is sent).
  const track = (name, p = {}) => { try { if (window.gtag) window.gtag('event', name, p); else if (window.dataLayer) window.dataLayer.push({ event: name, ...p }); } catch (e) {} };
  document.addEventListener('click', (e) => {
    const a = e.target.closest && e.target.closest('a[href]'); if (!a) return; const h = a.getAttribute('href') || '';
    if (h.startsWith('tel:')) track('call_click', { page_path: location.pathname }); else if (h.indexOf('wa.me/') > -1) track('whatsapp_click', { page_path: location.pathname });
  });
  const store = {
    get(k) { try { return JSON.parse(localStorage.getItem(k)) || []; } catch (e) { return []; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch (e) { return false; } }
  };

  // Mobile menu
  const btn = $('#menu-btn'), nav = $('#mobile-nav');
  if (btn && nav) btn.addEventListener('click', () => {
    const hidden = nav.classList.toggle('hidden');
    btn.setAttribute('aria-expanded', String(!hidden));
  });

  // Booking submission. 'supabase' mode calls the validated submit_booking() database function.
  // Success is reported only when the database returns a booking reference.
  const ERR = { invalid_phone: 'Enter a valid Pakistani mobile number.', invalid_name: 'Enter your name.', invalid_city: 'Choose a city we serve.', invalid_service: 'Choose an available service.',
    invalid_date: 'Choose a date from today up to six months ahead.', invalid_time: 'Choose a valid time.', too_long: 'Your description is too long.', rate_limited: 'Too many requests from this number. Please call or use WhatsApp.' };
  const sheetPost = (p, ref) => fetch(C.sheetsUrl, { method: 'POST', keepalive: true, headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify({ token: p.token, ref, name: p.name, phone: p.phone, city: p.city, service: p.category, serviceName: (C.services.find((x) => x.slug === p.category) || {}).name || '', item: p.item, problem: p.problem, date: p.date, time: p.time, source: location.pathname }) }).then((r) => r.json());
  function submitBooking(p) {
    if (C.bookingMode === 'dev') {
      const list = store.get('iserve_dev_bookings'); list.push({ ...p, at: new Date().toISOString() });
      return Promise.resolve({ saved: false, localOnly: store.set('iserve_dev_bookings', list) });
    }
    if (C.bookingMode === 'sheets') return sheetPost(p).then((b) => { if (b && b.ok) return { saved: true, ref: b.ref }; const e = new Error(ERR[b && b.error] || 'The request could not be saved.'); e.known = !!ERR[b && b.error]; throw e; });
    return fetch(`${C.supabaseUrl}/rest/v1/rpc/submit_booking`, { method: 'POST',
      headers: { apikey: C.supabaseAnonKey, ...(C.supabaseAnonKey.startsWith('eyJ') ? { Authorization: `Bearer ${C.supabaseAnonKey}` } : {}), 'Content-Type': 'application/json' },
      body: JSON.stringify({ p: { client_token: p.token, name: p.name, phone: p.phone, city: p.city, service: p.category, item: p.item, problem: p.problem, date: p.date, time: p.time, source: location.pathname } }) })
      .then((r) => r.json().then((b) => { if (!r.ok) { const e = new Error(ERR[b && b.message] || 'The request could not be saved.'); e.known = !!ERR[b && b.message]; throw e; }
        if (C.sheetsUrl) { try { sheetPost(p, b).catch(() => {}); } catch (x) {} }  /* optional copy to Google Sheets; the database save is what counts */
        return { saved: true, ref: b }; }));
  }

  const PK = /^(?:\+?92|0)?3\d{9}$/;
  const initForms = () => $$('form[data-booking]').forEach((f) => {
    const g = (n) => f.elements[n];
    const err = (n, m) => { const e = $(`[data-err="${n}"]`, f); if (e) e.textContent = m || ''; g(n).setAttribute('aria-invalid', m ? 'true' : 'false'); };
    const cityName = (s) => (C.cities.find((c) => c.slug === s) || {}).name || '';
    const svc = (s) => C.services.find((x) => x.slug === s);

    g('city').innerHTML = '<option value="">Select city</option>' + C.cities.map((c) => `<option value="${c.slug}">${c.name}</option>`).join('');
    g('category').innerHTML = '<option value="">Select service</option>' + C.services.map((s) => `<option value="${s.slug}">${s.name}</option>`).join('');
    const fillItems = () => {
      const s = svc(g('category').value);
      g('specific').innerHTML = '<option value="">Not sure, inspection needed</option>' + (s ? s.items.map((i) => `<option>${i}</option>`).join('') : '');
    };
    g('category').addEventListener('change', fillItems);
    if (f.dataset.city) g('city').value = f.dataset.city;
    if (f.dataset.service) g('category').value = f.dataset.service;
    fillItems();
    const d = g('date'); d.min = new Date().toISOString().slice(0, 10);

    const read = () => ({
      name: g('name').value.trim(), phone: g('phone').value.replace(/[\s-]/g, ''), city: g('city').value,
      category: g('category').value, item: g('specific').value, problem: g('problem').value.trim(),
      date: g('date').value, time: g('time').value
    });
    const message = (p) => `Hello IServe, I would like to book ${p.item || (svc(p.category) || {}).name || 'a home service'}` +
      `${p.city ? ' in ' + cityName(p.city) : ''}.` + `${p.problem ? ' Problem: ' + p.problem + '.' : ''}` +
      `${p.date ? ' Preferred date: ' + p.date + (p.time ? ' (' + p.time + ')' : '') + '.' : ''} Name: ${p.name}. Phone: ${p.phone}.`;

    function validate(p) {
      const e = {};
      if (p.name.length < 2) e.name = 'Enter your name (at least 2 characters).';
      if (!PK.test(p.phone)) e.phone = 'Enter a Pakistani mobile number, for example 0311 7420474.';
      if (!p.city) e.city = 'Choose your city.';
      if (!p.category) e.category = 'Choose a service.';
      if (p.problem.length > 500) e.problem = 'Keep the description under 500 characters.';
      if (p.date && p.date < d.min) e.date = 'Choose today or a later date.';
      ['name', 'phone', 'city', 'category', 'problem', 'date'].forEach((n) => err(n, e[n]));
      return e;
    }

    f.addEventListener('submit', (ev) => {
      ev.preventDefault();
      const p = read(), e = validate(p), out = $('[data-result]', f), sb = $('button[type=submit]', f);
      f._tok = f._tok || (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random()); p.token = f._tok;
      out.className = 'mt-4'; out.innerHTML = '';
      const first = Object.keys(e)[0];
      if (first) { g(first).focus(); return; }
      if (g('website').value) return; // honeypot
      sb.disabled = true; sb.textContent = 'Sending...';
      submitBooking(p).then((r) => {
        if (r.saved) { try { sessionStorage.setItem('iserve_submitted', '1'); sessionStorage.setItem('iserve_ref', r.ref); } catch (x) {} location.href = 'thank-you.html'; return; }
        sb.disabled = false; sb.textContent = 'Request booking';
        out.className = 'mt-4 rounded-lg border border-orange bg-orange/10 p-4 text-sm text-ink';
        out.innerHTML = '<p class="font-semibold text-navy">Development mode: this request was not sent to IServe.</p>' +
          '<p class="mt-1">The booking system is not connected yet' + (r.localOnly ? ', so your details are only kept in this browser' : '') +
          '. To book now, send them on WhatsApp or call ' + C.phoneDisplay + '.</p>' +
          `<div class="mt-3 flex flex-wrap gap-2"><a class="btn btn-wa" href="${wa(message(p))}" target="_blank" rel="noopener">Send on WhatsApp</a>` +
          `<a class="btn btn-navy" href="tel:${C.phone}">Call ${C.phoneDisplay}</a></div>`;
      }).catch((x) => {
        sb.disabled = false; sb.textContent = 'Request booking';
        out.className = 'mt-4 rounded-lg border border-red-700 bg-red-50 p-4 text-sm text-red-800';
        out.innerHTML = '<p class="font-semibold"></p><div class="mt-3 flex flex-wrap gap-2"><a class="btn btn-wa" target="_blank" rel="noopener">Send on WhatsApp instead</a><a class="btn btn-navy">Call</a></div>';
        $('p', out).textContent = (x.known ? x.message : 'Your request was not saved. Your details are still in the form, so you can try again.') + ' Nothing was submitted.';
        const l = $$('a', out); l[0].href = wa(message(p)); l[1].href = 'tel:' + C.phone; l[1].textContent = 'Call ' + C.phoneDisplay;
      });
    });
  });

  // Thank-you page guard: only confirm if a real submission set the flag.
  const initThanks = () => { const ty = $('[data-thanks]');
  if (ty) {
    let ok = false; try { ok = sessionStorage.getItem('iserve_submitted') === '1'; } catch (e) {}
    if (ok) { try { if (!sessionStorage.getItem('iserve_lead_sent')) { track('generate_lead', { page_path: location.pathname }); sessionStorage.setItem('iserve_lead_sent', '1'); } } catch (e) {} }
    $('[data-thanks-yes]').hidden = !ok; try { const r = sessionStorage.getItem('iserve_ref'); if (ok && r) $('[data-ref]').textContent = 'Reference: ' + r; } catch (e) {} $('[data-thanks-no]').hidden = ok;
  }
  };
  const initReveal = () => {
    const els = $$('.reveal:not(.in)');
    if (!('IntersectionObserver' in window)) { els.forEach((e) => e.classList.add('in')); return; }
    const io = new IntersectionObserver((en) => en.forEach((x) => { if (x.isIntersecting) { x.target.classList.add('in'); io.unobserve(x.target); } }), { rootMargin: '0px 0px -6% 0px', threshold: 0.05 });
    els.forEach((e) => io.observe(e));
  };
  const init = () => { initForms(); initThanks(); initReveal(); };
  init(); window.IServeInit = init;
})();
